mapper.select:
SELECT t.*
FROM system_schedule_task t

    t.deleted_flag = 'N'

        AND t.organization_id = #{filter.organizationId}


        AND t.app_id = #{filter.appId}


        AND t.source = #{filter.source}


        AND t.trigger_type = #{filter.triggerType}


        AND t.status = #{filter.status}


        AND t.action_type = #{filter.actionType}


        AND t.created_by = #{filter.createdBy}



        AND (t.title LIKE CONCAT('%', #{filter.keyword}, '%')
          OR t.task_code LIKE CONCAT('%', #{filter.keyword}, '%')
          OR t.biz_key LIKE CONCAT('%', #{filter.keyword}, '%'))


ORDER BY t.created_time DESC
